/* CBS people service (GET cbs-people-svc, loaded on every page by cbs-nav). Who is offered in each name picker comes from the Team "Appears in" ticks.
   CBSPeople.ready().then(...)            loads the Team list once
   CBSPeople.names(key[, keep])           active people ticked for key (crew, tasks, rams, coshh, cphsp, checks, toolbox, permits, incidents, po, survey, diary, docs, director, sm8, site_lead);
                                          if nobody is ticked for key yet, everyone active (so nothing disappears until someone is ticked); keep = names already on the record, always included.
   CBSPeople.all()                        everyone active (open lists: attendees, people involved, training).
   Pickers tagged data-people="key" (select, or the datalist behind an input) are filtered automatically; the selected/saved name is never removed.
   Builders (RAMS, CPHSP, CoSHH, toolbox talk, team meeting, incident report, pre-start, PO, inspections, permits, survey) are tagged here by the
   picker's label (Prepared by, Site lead, Approved by, Presented by, Assessed by, Signed off by, Ordered by, Inspected by, Issued by, Surveyor...),
   only when the picker actually lists people (never filter dropdowns like "All people"). Assigned to / Assignee (job tasks, programme, snags) = Tasks tick;
   companies in those lists are not people, so they always stay. Open lists stay open: attendees, person involved, name of person, reported by. */
(function(){if(window.CBSPeople)return;
var W=null,P=null,KEYS={crew:1,tasks:1,rams:1,coshh:1,cphsp:1,checks:1,toolbox:1,permits:1,incidents:1,po:1,survey:1,diary:1,docs:1,director:1,sm8:1,site_lead:1};
function on(v){return v===true||v==='true';}
function act(w){return !(w.active===false||w.active==='false');}
function nm(w){return String(w&&w.name||'').trim();}
function load(){if(P)return P;P=fetch('/webhook/cbs-admin-data?t=workers').then(function(r){return r.json();}).then(function(d){W=((d&&d.workers)||[]).filter(function(w){return w&&nm(w);});return W;})['catch'](function(){W=null;P=null;return [];});return P;}
function all(){return W?W.filter(act).map(nm):[];}
function names(key,keep){if(!W)return null;var A=W.filter(act),out;
 if(!key||!KEYS[key])out=A.map(nm);
 else{var col=key==='site_lead'?'site_lead':'in_'+key,T=A.filter(function(w){return on(w[col]);});out=(T.length?T:A).map(nm);}
 (keep||[]).forEach(function(k){k=String(k||'').trim();if(k&&out.indexOf(k)<0)out.push(k);});
 return out.sort(function(a,b){return a.localeCompare(b);});}
function isPerson(t){t=String(t||'').trim();return !!t&&!!W&&W.some(function(w){return nm(w)===t;});}
/* --- builders: tag name pickers by their label --- */
var PATH=location.pathname;
function docKey(){return /rams/.test(PATH)?'rams':/cphsp|cdm/.test(PATH)?'cphsp':/coshh/.test(PATH)?'coshh':/survey/.test(PATH)?'survey':/permit/.test(PATH)?'permits':'docs';}
function keyFor(l){l=String(l||'').replace(/\s+/g,' ').trim().toLowerCase();if(!l)return '';
 if(/attendee|who attended|person involved|name of person|injured|reported by|witness|visitor|^people$/.test(l))return '';
 if(/approv(ed|er)\s*by|^approved|director/.test(l))return 'director';
 if(/site lead|supervisor|running the pre-start|site manager/.test(l))return 'site_lead';
 if(/present(ed|er)|chaired|delivered by|led by/.test(l)||(l==='by'&&/toolbox|meeting/.test(PATH)))return 'toolbox';
 if(/assess(ed|or|ment carried out)/.test(l))return 'coshh';
 if(/signed off by|investigat/.test(l)&&/incident/.test(PATH))return 'incidents';
 if(/(ordered|received|raised|requested) by/.test(l)&&/(^|[^a-z])po([^a-z]|$)|purchase|order/.test(PATH))return 'po';
 if(/inspected by|inspector|carried out by|checked by|completed by/.test(l)&&/insp|check|prestart|pre-use|scaff/.test(PATH))return 'checks';
 if(/issued by|authoris|permit holder|competent person/.test(l)&&/permit/.test(PATH))return 'permits';
 if(/surveyor|surveyed by/.test(l))return 'survey';
 if(/prepared by|responsible person|written by|author/.test(l))return docKey();
 if(/assign(ed)?\s*to|assignee|who is doing/.test(l))return 'tasks';
 return '';}
function labelOf(el){var t='';try{if(el.id){var f=document.querySelector('label[for="'+el.id.replace(/"/g,'')+'"]');if(f)t=f.textContent;}
 if(!t){var lb=el.closest('label');if(lb){var c=lb.cloneNode(true);[].forEach.call(c.querySelectorAll('select,option,datalist,input,textarea,button'),function(x){x.remove();});t=c.textContent;}}
 if(!t){var p=el.previousElementSibling;if(p&&!/^(SELECT|INPUT|TEXTAREA|BUTTON)$/.test(p.tagName))t=p.textContent;}
 if(!t&&el.parentElement){var c2=el.parentElement.cloneNode(true);[].forEach.call(c2.querySelectorAll('select,option,datalist,input,textarea,button'),function(x){x.remove();});t=c2.textContent;}
 if(!t)t=el.getAttribute('aria-label')||el.getAttribute('placeholder')||el.name||'';}catch(e){}return String(t).slice(0,80);}
function isFilter(el){var o=el.querySelectorAll('option');for(var i=0;i<o.length&&i<3;i++)if(/^(all|any|everyone|anyone|no filter)\b/i.test(String(o[i].textContent).trim()))return true;return false;}
function listsPeople(el){var o=el.querySelectorAll('option'),n=0;for(var i=0;i<o.length&&n<2;i++)if(isPerson(o[i].value||o[i].textContent))n++;return n>=2;}
function tag(){if(!W)return;
 [].forEach.call(document.querySelectorAll('select:not([data-people]):not([data-ppl-done])'),function(s){if(!listsPeople(s)||isFilter(s))return;s.setAttribute('data-ppl-done','1');var k=keyFor(labelOf(s));if(k)s.setAttribute('data-people',k);});
 [].forEach.call(document.querySelectorAll('input[list]:not([data-ppl-done])'),function(i){var d=document.getElementById(i.getAttribute('list'));if(!d||d.hasAttribute('data-people')||!listsPeople(d))return;i.setAttribute('data-ppl-done','1');var k=keyFor(labelOf(i));if(k)d.setAttribute('data-people',k);});}
function curVal(el){if(el.tagName==='DATALIST'){var i=document.querySelector('input[list="'+el.id+'"]');return i?i.value:'';}return el.value||'';}
function apply(){if(!W)return;tag();var els=document.querySelectorAll('[data-people]');for(var i=0;i<els.length;i++){var el=els[i],key=el.getAttribute('data-people');
  var opts=el.tagName==='SELECT'||el.tagName==='DATALIST'?el.querySelectorAll('option'):[];if(!opts.length)continue;
  var v=curVal(el),sig=key+'|'+opts.length+'|'+v;if(el.__cbsPpl===sig)continue;
  var ok=names(key,[v]);for(var j=0;j<opts.length;j++){var o=opts[j],t=String(o.value||o.textContent||'').trim();
   if(!t||o.selected||!isPerson(t))continue;if(ok.indexOf(t)<0)o.remove();}
  el.__cbsPpl=key+'|'+el.querySelectorAll('option').length+'|'+v;}}
var tm=null;function soon(){clearTimeout(tm);tm=setTimeout(apply,120);}
window.CBSPeople={ready:load,names:names,all:all,apply:apply,keyFor:keyFor};
load().then(function(){apply();try{new MutationObserver(function(ms){for(var i=0;i<ms.length;i++){var t=ms[i].target;if(t&&t.closest&&t.closest('[data-people]')||(ms[i].addedNodes&&ms[i].addedNodes.length)){soon();return;}}}).observe(document.documentElement,{childList:true,subtree:true});}catch(e){}});
})();

