/* Hub sign-in service (POST cbs-signin-act). Records live in cbs_signin (private: internal key only) via cbs-admin-save.
   a=names: who can sign in (Team people with Hub sign-in ticked; nobody ticked yet = everyone employed) and whether each has a PIN.
   a=login {name,pin,pin2?,device}: first sign-in sets the PIN (entered twice); returns a session token (30 days).
   a=check {token}: {ok,name} while the session is live (last_seen updated at most hourly).
   a=logout {token}. Signed-in only: a=manage (people, PIN set or not, live sessions), a=kill {id}, a=resetpin {name}.
   PINs are stored only as a SHA-256 hash of name + PIN. */
const H='https://old-hub.example/webhook/',K='[redacted-internal-key]',h=this.helpers;
const S=v=>v==null?'':String(v).trim();
let b=$input.first().json.body||{};if(typeof b==='string'){try{b=JSON.parse(b);}catch(e){b={};}}
const a=S(b.a),R=x=>[{json:x}],now=new Date().toISOString(),DAY=864e5;
const list=async t=>{const r=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t+'&k='+K,body:{},json:true});return Array.isArray(r)?r:[];};
const save=(id,row,partial)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=signin&id='+(id||0)+'&k='+K+(partial?'&partial=1':''),body:row,json:true});
function sha256(m){function r(n,x){return(x>>>n)|(x<<(32-n));}var k=[],i,j,H0=[1779033703,3144134277,1013904242,2773480762,1359893119,2600822924,528734635,1541459225];
 var p=2,c=0;while(c<64){var ok=true;for(j=2;j*j<=p;j++)if(p%j===0){ok=false;break;}if(ok){k[c++]=(Math.pow(p,1/3)%1)*4294967296|0;}p++;}
 var s=unescape(encodeURIComponent(m)),l=s.length*8,w=[];for(i=0;i<s.length;i++)w[i>>2]|=(s.charCodeAt(i)&255)<<(24-(i%4)*8);
 w[l>>5]|=128<<(24-l%32);w[((l+64>>9)<<4)+15]=l;
 for(i=0;i<w.length;i+=16){var a2=H0.slice(0),W=[];for(j=0;j<64;j++){if(j<16)W[j]=w[i+j]|0;else{var x=W[j-15],y=W[j-2];W[j]=(W[j-16]+(r(7,x)^r(18,x)^(x>>>3))+W[j-7]+(r(17,y)^r(19,y)^(y>>>10)))|0;}
  var t1=a2[7]+(r(6,a2[4])^r(11,a2[4])^r(25,a2[4]))+((a2[4]&a2[5])^(~a2[4]&a2[6]))+k[j]+W[j],t2=(r(2,a2[0])^r(13,a2[0])^r(22,a2[0]))+((a2[0]&a2[1])^(a2[0]&a2[2])^(a2[1]&a2[2]));
  a2=[(t1+t2)|0].concat(a2);a2[4]=(a2[4]+t1)|0;a2.length=8;}
  for(j=0;j<8;j++)H0[j]=(H0[j]+a2[j])|0;}
 return H0.map(function(v){return('00000000'+(v>>>0).toString(16)).slice(-8);}).join('');}
const hash=(name,pin)=>sha256('[redacted-salt]|'+name.toLowerCase()+'|'+pin);
const on=v=>v===true||v==='true';
async function people(){const W=(await list('workers')).filter(w=>!(w.active===false||w.active==='false')&&S(w.name));const T=W.filter(w=>on(w.hub_signin));return (T.length?T:W).map(w=>S(w.name)).sort((x,y)=>x.localeCompare(y));}
const live=r=>S(r.active)!=='0';
async function session(t){if(!t)return null;const L=await list('signin');const s=L.find(r=>r.kind==='session'&&S(r.token)===t&&live(r));if(!s)return null;
 if(Date.now()-Date.parse(s.created_at||0)>30*DAY){await save(s.id,{active:'0'},true);return null;}return {s,L};}
if(a==='names'){const P=await people();const L=await list('signin');const pins={};L.forEach(r=>{if(r.kind==='pin'&&live(r)&&S(r.pin_hash))pins[S(r.name)]=1;});
 return R({ok:true,people:P.map(n=>({name:n,pin:!!pins[n]}))});}
if(a==='login'){const name=S(b.name),pin=S(b.pin),dev=S(b.device).slice(0,120);
 if(!/^\d{4}$/.test(pin))return R({ok:false,message:'Enter your 4-digit PIN.'});
 const P=await people();if(P.indexOf(name)<0)return R({ok:false,message:'That name cannot sign in. Ask the office to tick Hub sign-in in Team.'});
 const L=await list('signin');const pr=L.find(r=>r.kind==='pin'&&S(r.name)===name&&live(r)&&S(r.pin_hash));
 if(!pr){if(S(b.pin2)!==pin)return R({ok:false,setPin:true,message:'The two PINs do not match. Try again.'});
  await save(0,{kind:'pin',name:name,pin_hash:hash(name,pin),token:'',device:'',created_at:now,last_seen:'',active:'1'});}
 else if(S(pr.pin_hash)!==hash(name,pin)){await new Promise(z=>setTimeout(z,900));return R({ok:false,message:'Wrong PIN. Try again.'});}
 let tok='';for(let i=0;i<5;i++)tok+=Math.random().toString(36).slice(2,10);
 await save(0,{kind:'session',name:name,pin_hash:'',token:tok,device:dev,created_at:now,last_seen:now,active:'1'});
 return R({ok:true,token:tok,name:name});}
if(a==='check'){const x=await session(S(b.token));if(!x)return R({ok:false});
 if(Date.now()-Date.parse(x.s.last_seen||0)>3600e3)await save(x.s.id,{last_seen:now},true);return R({ok:true,name:S(x.s.name)});}
if(a==='logout'){const x=await session(S(b.token));if(x)await save(x.s.id,{active:'0'},true);return R({ok:true});}
const x=await session(S(b.token));if(!x)return R({ok:false,signin:true,message:'Please sign in again.'});
if(a==='manage'){const P=await people();const L=x.L;
 const rows=P.map(n=>({name:n,pin:L.some(r=>r.kind==='pin'&&S(r.name)===n&&live(r)&&S(r.pin_hash)),
  sessions:L.filter(r=>r.kind==='session'&&S(r.name)===n&&live(r)&&Date.now()-Date.parse(r.created_at||0)<=30*DAY).map(r=>({id:r.id,device:S(r.device),created_at:S(r.created_at),last_seen:S(r.last_seen),me:S(r.token)===S(b.token)}))}));
 return R({ok:true,me:S(x.s.name),people:rows});}
if(a==='kill'){const id=Number(b.id)||0;const s=x.L.find(r=>Number(r.id)===id&&r.kind==='session');if(!s)return R({ok:false,message:'Not found.'});await save(id,{active:'0'},true);return R({ok:true});}
if(a==='resetpin'){const name=S(b.name);const ps=x.L.filter(r=>r.kind==='pin'&&S(r.name)===name&&live(r));for(const p of ps)await save(p.id,{active:'0'},true);
 const ss=x.L.filter(r=>r.kind==='session'&&S(r.name)===name&&live(r));for(const s of ss)await save(s.id,{active:'0'},true);return R({ok:true});}
return R({ok:false,message:'Unknown action.'});

/* Hub sign-in page (GET cbs-signin): pick your name, then your 4-digit PIN (first time: choose it, entered twice). ?next=<url> returns there
