const html='<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in - CBS Operations Hub</title><style>'+CSS+'</style></head><body><header><small>Chelmsford Building Services</small><b>Operations Hub</b></header><main id="app"><div class="msg">Loading\u2026</div></main><script>('+signin.toString()+')();</script></body></html>';
