/* Job summary data (GET cbs-job-summary-data?job=N): one job only. ServiceM8 (job status, folder, scheduled activities) from the SM8 Sum nodes,
   plus hub feeds: tasks (cbs-tasks-data), programme (cbs-programme-data), requirements (cbs-job-reqs-data, cached), files (cbs-job-files).
   All read-only. The result is cached per job for 2 minutes in this workflow's static data (SD Fresh answers from it). */
const H='https://old-hub.example/webhook/',h=this.helpers;
const S=v=>v==null?'':String(v).trim();
const job=S($('Summary Data Hook').first().json.query.job).replace(/[^0-9A-Za-z-]/g,'');
const all=n=>{try{return $(n).all().map(i=>i.json).filter(x=>x&&x.uuid);}catch(e){return [];}};
const J=all('SM8 Sum Job')[0]||null,A=all('SM8 Sum Acts'),Q={};all('SM8 Sum Queues').forEach(q=>Q[q.uuid]=S(q.name));
const today=new Date().toISOString().slice(0,10);
const get=async(u)=>{try{return await h.httpRequest({method:'GET',url:H+u,json:true,timeout:45000});}catch(e){return null;}};
const [T,P,F]=await Promise.all([get('cbs-tasks-data?job='+encodeURIComponent(job)),get('cbs-programme-data?job='+encodeURIComponent(job)),get('cbs-job-files?job='+encodeURIComponent(job))]);
let R=null;try{R=await h.httpRequest({method:'POST',url:H+'cbs-job-reqs-data',body:{},json:true,timeout:60000});}catch(e){}
const tj=(T&&T.jobs&&T.jobs[job])||{};
const status=J?(S(J.status)==='Quote'?'Estimate':S(J.status)==='Work Order'?(S(tj.stage)||'Approved'):S(J.status)):(S(tj.stage)||'');
const folder=J?(Q[S(J.queue_uuid)]||(S(J.queue_uuid)?'':'No folder')):'';
const sch=A.filter(a=>String(a.active)==='1'&&String(a.activity_was_scheduled)==='1'&&S(a.start_date));
const fut=sch.filter(a=>S(a.end_date||a.start_date).slice(0,10)>=today).sort((a,b)=>S(a.start_date).localeCompare(S(b.start_date)));
const past=sch.filter(a=>S(a.end_date||a.start_date).slice(0,10)<today).sort((a,b)=>S(b.start_date).localeCompare(S(a.start_date)));
const days=new Set(fut.map(a=>S(a.start_date).slice(0,10))),crew=new Set(fut.map(a=>S(a.staff_uuid)).filter(Boolean));
const booked=fut.length?{next:S(fut[0].start_date).slice(0,10),days:days.size,crew:crew.size}:(past.length?{last:S(past[0].start_date).slice(0,10)}:null);
const tc=(T&&T.counts)||{};const tasks=(T&&Array.isArray(T.tasks))?T.tasks:[];
const ps=(P&&P.summary)||{};const prog=P?{pct:Number(ps.pct)||0,current:S(ps.current),phases:Number(ps.phases)||0,overdue:Number(ps.overdue)||0,status:S(ps.status),draft:!!ps.draft,has:!!(ps.phases||ps.items)}:null;
const items=((R&&R.items)||[]).filter(x=>S(x.job)===job).map(x=>({l:S(x.l),st:S(x.st),note:S(x.note),link:S(x.link)}));
const links=((R&&R.links)||[]).filter(x=>S(x.job)===job&&x.rec).map(x=>({l:S(x.rec.no||x.rec.name||x.req),st:'done',note:S(x.rec.st),link:S(x.rec.url)}));
const before=links.concat(items);
const act=[];((F&&F.folders)||[]).forEach(fo=>(fo.files||[]).forEach(f=>{if(S(f.at))act.push({at:S(f.at),t:'File added to '+S(fo.name)+': '+S(f.n)});}));
tasks.forEach(t=>{const d=S(t.done_at||t.completed_at);if(d)act.push({at:d,t:'Task done: '+S(t.title||t.label||t.name)+(S(t.done_by)?' ('+S(t.done_by)+')':'')});});
act.sort((a,b)=>b.at.localeCompare(a.at));
const out={ok:true,job:job,at:new Date().toISOString(),client:S(tj.client)||'',desc:S(tj.desc)||S(J&&J.job_description).split('\n')[0],site:S(tj.site)||S(J&&J.job_address),type:S(tj.type),
 status:status,folder:folder,found:!!J,booked:booked,tasks:{open:Number(tc.open)||0,overdue:Number(tc.overdue)||0},prog:prog,before:before.slice(0,20),activity:act.slice(0,12)};
