/* CBS logo for the new layout's menu (GET cbs-logo). Taken from the hub page's own logo (img#cbsLogo in page:cbs-admin)
   once a day and kept in this workflow's static data, so the logo always matches the hub. */
const SD=$getWorkflowStaticData('global');let b=SD.logo||'',t=SD.logoType||'image/png';
if(!b||Date.now()-(SD.logoAt||0)>86400000){try{const s=String(await this.helpers.httpRequest({method:'GET',url:'https://old-hub.example/webhook/cbs-admin',json:false,timeout:60000}));
 const m=s.match(/<img id="cbsLogo"[^>]*src="data:(image\/[a-z+]+);base64,([A-Za-z0-9+\/=]+)"/);if(m){t=m[1];b=m[2];SD.logo=b;SD.logoType=t;SD.logoAt=Date.now();}}catch(e){}}
