/* Layout store (POST cbs-layout-patch, internal key). Keeps the new-layout script (cbs-layout-js) in this workflow's static data
   so changes are sent as small find/replace patches instead of the whole script. First call seeds it from the current script.
   Body: {key, patches:[{find,replace}], seed?:true, get?:true}. Each find must match exactly once or nothing is saved. */
const b=$input.first().json.body||{};if(b.key!=='[redacted-internal-key]')return [{json:{ok:false,error:'bad key'}}];
const SD=$getWorkflowStaticData('global');
if(!SD.layout||b.seed){const s=String(await this.helpers.httpRequest({method:'GET',url:'https://old-hub.example/webhook/cbs-layout-js',json:false,timeout:30000}));if(!SD.layout)SD.layoutPrev='';SD.layout=s;}
let L=SD.layout;const res=[];
for(const p of (b.patches||[])){const f=String(p.find||''),r=String(p.replace==null?'':p.replace);const i=L.indexOf(f);if(!f||i<0)return [{json:{ok:false,error:'not found',find:f.slice(0,120),done:res.length}}];if(L.indexOf(f,i+1)>-1)return [{json:{ok:false,error:'found more than once',find:f.slice(0,120),done:res.length}}];L=L.slice(0,i)+r+L.slice(i+f.length);res.push(f.length+'>'+r.length);}
try{new Function(L);}catch(e){return [{json:{ok:false,error:'script error: '+e.message}}];}
if((b.patches||[]).length){SD.layoutPrev=SD.layout;SD.layout=L;SD.layoutAt=new Date().toISOString();}
let h=0;for(let i=0;i<L.length;i++){h=(h*31+L.charCodeAt(i))>>>0;}
return [{json:{ok:true,applied:res.length,chars:L.length,hash:h,at:SD.layoutAt||null,text:b.get?L:undefined}}];

